-- public.worker_idle(p_world uuid, c creature, p_kind text, p_x integer, p_y integer, p_radius integer, p_post bigint)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.worker_idle(p_world uuid, c creature, p_kind text, p_x integer, p_y integer, p_radius integer, p_post bigint)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare v_since timestamptz; v_hard record; v_where text;
begin
  if c.keeper is null then return; end if;
  select idle_since into v_since from creature where world_id = p_world and id = c.id;
  -- Empty for a moment is between jobs; empty for an hour is stuck.
  if v_since is null or v_since > now() - idle_before_telling() then return; end if;
  -- The same ten minutes, off the same stamp, as `worker_nowhere`.
  if (select told_at from creature where world_id = p_world and id = c.id) > now() - interval '10 minutes'
    then return; end if;
  update creature set told_at = now() where world_id = p_world and id = c.id;

  v_where := case when p_post is not null then 'its work post' when c.around is not null then 'you' else 'the totem' end
             || ' at ' || p_x || ',' || p_y;

  -- A face it would take but for the skill. Only mining has levels on it.
  if p_kind = 'mine' then
    select * into v_hard from seam_beyond(p_world, p_x, p_y, p_radius, c);
    if v_hard.x is not null then
      perform wtell(p_world, c.keeper, c.name || ' idle: nothing it can mine within '
        || p_radius || ' tiles of ' || v_where || '. ' || v_hard.what || ' at '
        || v_hard.x || ',' || v_hard.y || ' needs mining '
        || rtrim(rtrim(to_char(v_hard.want, 'FM990.99'), '0'), '.')
        || '; ' || c.name || ' has ' || to_char(task_skill(c), 'FM990.0') || ' and cannot level up on it. '
        || 'Needs a softer seam (copper and coal: 1) or a move.', 'error');
      return;
    end if;
  end if;

  perform wtell(p_world, c.keeper, c.name || ' idle: no ' || work_words(p_kind)
    || ' within ' || p_radius || ' tiles of ' || v_where || '. '
    || case when p_kind in ('mine', 'quarry')
         then 'Needs bare rock, not under soil or paving. '
         else '' end
    || 'Fix: a work post nearer the work, or more skill for more range.', 'error');
end $function$
